from content import *
c='careers_v18';p=lambda k:G(c,k);m=lambda k,v:M(c,k,v)
for k,v,lo,hi in [('Role',0,0,4),('Skill',25,0,100),('Reputation',20,0,100),('Fitness',40,0,100),('Technique',30,0,100),('Tactics',30,0,100),('Leadership',30,0,100),('Budget',500000,0,20000000),('Vehicle',0,0,3),('Forecast',30,0,100),('Safety',50,0,100),('Research',0,0,1000000),('Tours',0,0,1000000),('Wins',0,0,1000000),('Failures',0,0,1000000),('Actions',0,0,8),('PaidAge',-1,-1,999),('NativeCupRoll',0,0,1),('Roll',0,0,99)]:prop(c,k,v,lo,hi,reset=k=='Actions')
text(c,'RoleName','No added career');text(c,'ChaseReport','No storm surveyed');text(c,'ClubName','Choose a club');text(c,'Strategy','Balanced')
menu(c,'My Special Career',[tile('Storm Chaser',S('storm'),'v18-storm'),tile('Sports Manager',S('manager'),'clipboard'),tile('Sports Coach',S('coach18'),'whistle'),tile('Race Car Driver',S('racer18'),'race-car'),tile('Career Record',S('career_record'),'suitcase')],None,'suitcase','Storm chasing; management; coaching and racing')
gate=lambda target:logic([('(<hero:age> < 18)',S('career_young')),(f'({G("life_v18","Hospital")} == 1)',S('sports_hospital'))],target)
budget=lambda target:gate(logic([(f'({p("Actions")} >= 8)',S('career_limit'))],target))
add('career_young','Special careers','These special careers unlock at age 18.',[('Back',home(c))],icon='suitcase')
add('career_limit','Career schedule','You have used eight fieldwork or training actions at this age. Age up to refresh the schedule.',[('Back',home(c))],icon='calendar')
for key,role,label,icon in [('storm',1,'Storm Chaser','v18-storm'),('manager',2,'Sports Manager','clipboard'),('coach18',3,'Sports Coach','whistle'),('racer18',4,'Race Car Driver','race-car')]:
 add(key,label,'Take an added career contract, develop your skills and complete annual work. One added contract is active at a time.',[('Take this contract',gate(seq(m('Role',role),T(c,'RoleName',label),S(key+'_hub')))),('Open my career',logic([(f'({p("Role")} != {role})',S(key))],S(key+'_hub'))),('Back',home(c))],icon=icon)
add('storm_hub','Storm Chaser','Study forecasts, choose equipment and survey a storm. Research and safety planning improve success. A dangerous approach can fail without killing your character or NPCs.',[('Forecast and safety training',budget(seq(I(c,'Actions'),I(c,'Forecast',6),I(c,'Safety',4),S('storm_hub')))),('Choose chase vehicle',home('vehicles')),('Chase a storm',budget(seq(m('NativeCupRoll',1),S('chase_plan')))),('Annual contract / back',S('career_pay'))],icon='v18-storm',tables=table(Forecast=p('Forecast'),Safety=p('Safety'),Vehicle=p('Vehicle'),Survey_data=p('Research'),Successful_tours=p('Tours')))
menu('vehicles','Storm Chasing Vehicles',[tile(label,S('vehicle'+str(i)),'v18-truck') for i,label in [(0,'Weather Station / Walking Survey'),(1,'Radar Van'),(2,'Armoured Interceptor'),(3,'Mobile Research Lab')]])
for i,label in [(0,'Station Survey'),(1,'Radar Van'),(2,'Armoured Interceptor'),(3,'Mobile Research Lab')]:add('vehicle'+str(i),label,'Equipment is provided through your research contract.',[('Use this equipment',seq(m('Vehicle',i),S('storm_hub'))),('Back',home('vehicles'))],icon='v18-truck')
for i,label,bonus,risk in [(1,'Stay outside the danger area',20,15),(2,'Set up probes at a safe distance',10,25),(3,'Follow the storm closely',0,45)]:
 dest=logic([(f'({p("Roll")} < {F("clamp",F("add",20,F("div",p("Forecast"),2),F("div",p("Safety"),4),F("mul",p("Vehicle"),5),bonus),15,90)})',seq(I(c,'Actions'),I(c,'Tours'),I(c,'Research',15+i*10),I(c,'Reputation',3),T(c,'ChaseReport','Research collected; crew returned safely'),S('chase_report')))],seq(I(c,'Actions'),I(c,'Failures'),I(c,'Safety',-3 if risk>25 else 0),T(c,'ChaseReport','Survey aborted; review the forecast and safety plan'),S('chase_report')))
 if i==1:plans=[]
 plans.append((label,budget(dest)))
add('chase_plan','Storm approach','The forecast suggests severe weather. Choose an approach for your research crew.',plans+[('Back',S('storm_hub'))],icon='v18-storm')
add('chase_report','Storm survey',p('ChaseReport'),[('Continue',S('storm_hub'))],icon='v18-storm',tables=table(Research=p('Research'),Reputation=p('Reputation')))
add('manager_hub','Sports Manager','Control the club’s strategy, roster budget and recruiting. Transfers use the saved club budget, while your annual contract pays into the native bank balance.',[('Scout and recruit',budget(seq(I(c,'Actions'),m('Budget',F('max',0,F('sub',p('Budget'),25000))),I(c,'Technique',5),I(c,'Reputation',2),S('manager_hub')))),('Choose tactics',S('club_tactics')),('Play a club fixture',budget(seq(m('NativeCupRoll',1),S('club_fixture')))),('Annual contract / back',S('career_pay'))],icon='clipboard',tables=table(Club_budget=p('Budget'),Technique=p('Technique'),Tactics=p('Tactics'),Leadership=p('Leadership'),Wins=p('Wins')))
add('club_tactics','Club strategy','Set the manager’s tactical approach.',[(label,seq(T(c,'Strategy',label),I(c,'Tactics',2),I(c,'Actions'),S('manager_hub'))) for label in ['Attack','Defend','Balanced']]+[('Back',S('manager_hub'))],icon='clipboard')
fixture=logic([(f'({p("Roll")} < {F("clamp",F("add",25,F("div",p("Tactics"),3),F("div",p("Technique"),4)),25,80)})',seq(I(c,'Actions'),I(c,'Wins'),I(c,'Budget',10000),I(c,'Reputation',4),S('club_win')))],seq(I(c,'Actions'),I(c,'Failures'),I(c,'Reputation',-2),S('club_loss')))
add('club_fixture','Club fixture','Commit this fixture once. Better recruitment and tactics improve your chance of winning.',[('Play',budget(fixture)),('Back',S('manager_hub'))],icon='soccer-ball')
add('club_win','Club victory','Your club won the fixture.',[('Continue',S('manager_hub'))],icon='trophy')
add('club_loss','Club defeat','The opposition won. Review tactics and recruitment before the next fixture.',[('Continue',seq(M('soccer_v12','NativeConceded',1),S('manager_hub')))],icon='soccer-ball')
add('coach18_hub','Sports Coach','Develop fitness, technique, tactics, leadership and reputation. These English coaching attributes were adapted from the supplied Brazilian pack data.',[(label,budget(seq(I(c,'Actions'),I(c,field,6),I(c,'Reputation',2),M('sports_people_v14','NativeFitnessImpact',1),S('coach18_hub')))) for label,field in [('Fitness and conditioning','Fitness'),('Technical skill session','Technique'),('Tactics and leadership','Leadership')]]+[('Annual contract / back',S('career_pay'))],icon='whistle',tables=table(Fitness=p('Fitness'),Technique=p('Technique'),Tactics=p('Tactics'),Leadership=p('Leadership'),Reputation=p('Reputation')))
add('racer18_hub','Race Car Driver','Use the existing native Formula One career alongside these saved driver training and race activities.',[('Open native Formula One pack','BP_SHOW_LIST=genesis_v7_f1_career'),('Driver training',budget(seq(I(c,'Actions'),I(c,'Skill',6),I(c,'Technique',4),S('racer18_hub')))),('Race',budget(seq(m('NativeCupRoll',1),S('race18')))),('Annual contract / back',S('career_pay'))],icon='race-car',tables=table(Driver_skill=p('Skill'),Technique=p('Technique'),Wins=p('Wins'),Reputation=p('Reputation')))
add('race18','Race day','Choose how hard to push. Skill and technique affect the race result.',[(label,logic([(f'({p("Roll")} < {F("clamp",F("add",20,F("div",p("Skill"),2),F("div",p("Technique"),4),bonus),20,85)})',seq(I(c,'Actions'),I(c,'Wins'),I(c,'Reputation',4),S('race18_win')))],seq(I(c,'Actions'),I(c,'Failures'),S('race18_loss')))) for label,bonus in [('Push for the win',3),('Drive consistently',8),('Protect the tyres',5)]]+[('Back',S('racer18_hub'))],icon='race-car')
add('race18_win','Race victory','Your driving and setup earned the win.',[('Continue',S('racer18_hub'))],icon='trophy')
add('race18_loss','Race finished','You finished outside the winning position. Train and try a different strategy.',[('Continue',S('racer18_hub'))],icon='race-car')
paycases=[(f'({p("Role")} == {i})',seq(m('PaidAge','<hero:age>'),f'BP_BANK_BALANCE={salary}',S('paid18'))) for i,salary in [(1,85000),(2,125000),(3,90000),(4,200000)]]
add('career_pay','Annual career contract','Claim one salary payment per age from your current added career. The payment goes into the native bank balance.',[('Claim annual salary',gate(logic([(f'({p("Role")} == 0)',home(c)),(f'({p("PaidAge")} == <hero:age>)',S('already_paid'))]+paycases,home(c)))),('Career record',S('career_record')),('Back',home(c))],icon='money-bag')
add('already_paid','Salary already paid','Your current age’s payment has already been claimed.',[('Continue',home(c))],icon='money-bag')
add('paid18','Salary payment','Your contract’s salary has been added to your bank balance.',[('Continue',S('career_record'))],icon='money-bag')
add('career_record',p('RoleName'),'Your added contract record.',[('Back',home(c))],icon='suitcase',tables=table(Reputation=p('Reputation'),Wins=p('Wins'),Research=p('Research'),Actions_this_age=p('Actions'),Last_paid_age=p('PaidAge')))

for owner,label,target,icon in [('storm_career19','Storm Chaser','storm','v18-storm'),('manager_career19','Sports Manager','manager','chart-bar'),('coach_career19','Sports Coach','coach18','man-teacher'),('racer_career19','Race Car Driver','racer18','flag-checkered')]:
 prop(owner,'Version',19,hi=19)
 menu(owner,label,[tile('Start or continue '+label,S(target),icon),tile('Career Record',S('career_record'),'chart-up')],'SpecialCareers',icon,'Available from age 18')
